static int g_fail;
#define CHECK(c) do { if (!(c)) { g_fail++; printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)

static void check_vec(const char *name, const unsigned char *v, size_t n, size_t want, unsigned char (*expect)(int)) {
    unsigned char *out = malloc(want + 16);
    size_t got = cui__inflate(v, n, out, want + 16);
    int ok = got == want;
    for (size_t i = 0; ok && i < want; i++) ok = out[i] == expect((int)i);
    printf("inflate %-8s %s\n", name, ok ? "ok" : "FAILED");
    CHECK(ok);
    CHECK(cui__inflate(v, n, out, want - 1) == 0);           /* output too small */
    for (size_t cut = 0; cut < n; cut += 1 + n / 64)          /* truncated input never succeeds */
        CHECK(cui__inflate(v, cut, out, want + 16) != want);
    unsigned char *bad = malloc(n);
    srand(1);
    for (int t = 0; t < 2000; t++) {                          /* flipped bits must not crash */
        memcpy(bad, v, n);
        for (int k = 0; k < 3; k++) bad[rand() % n] ^= (unsigned char)(1 << (rand() % 8));
        (void)cui__inflate(bad, n, out, want + 16);
    }
    free(bad);
    free(out);
}

int main(void) {
    size_t text_len = 45 * 40 + 256;
    check_vec("stored", v_stored, sizeof v_stored, text_len, expect_text);
    check_vec("fixed", v_fixed, sizeof v_fixed, text_len, expect_text);
    check_vec("dynamic", v_dynamic, sizeof v_dynamic, text_len, expect_text);
    check_vec("rle", v_rle, sizeof v_rle, 8000, expect_rle);
    printf("%s\n", g_fail ? "inflate: FAILED" : "inflate: all ok");
    return g_fail != 0;
}
